export function appPage(env){
  const isProduction=deployment(env)?.label==='production';
  const nonce=crypto.randomUUID().replaceAll('-','');
  const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>ADMAKI Menu · Sign in</title><style nonce="${nonce}">${css}${dashboardCss}${workspaceCss}</style></head><body><aside id="dashboard-sidebar" hidden aria-label="Dashboard sidebar"></aside><header><strong>ADMAKI MENU ${isProduction?'':'<small>· Staging</small>'}</strong><nav aria-label="Account"></nav></header><div id="flash" role="status"></div><main><p>Loading your account…</p></main><footer>ADMAKI Digital${isProduction?'':' · Private staging environment'}</footer><script nonce="${nonce}">const useProductionLogin=${isProduction};${js}</script></body></html>`;
  return new Response(html,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff','X-Robots-Tag':'noindex, nofollow','Referrer-Policy':'no-referrer','X-Frame-Options':'DENY',
    'Content-Security-Policy':`default-src 'none'; script-src 'nonce-${nonce}'; style-src 'nonce-${nonce}'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; form-action 'self'; frame-ancestors 'none'`}});
}
